import {createCityAmbience,showAmbienceSettings} from './city-ambience.js?v=reward-garbage-1';
import {createGameMusic,showMusicSettings} from './game-music.js?v=reward-garbage-1';
const KEY='sims3000-audio';
export const AUDIO_CUES={notice:[[523.25,523.25,.45,0],[783.99,783.99,.65,.16],[1046.5,1046.5,.8,.32]],achievement:[[261.63,261.63,.32,0],[329.63,329.63,.32,.15],[392,392,.32,.3],[523.25,523.25,.9,.48],[659.25,659.25,.9,.48],[783.99,783.99,.9,.48]],tension:[[220,196,.28,0],[220,196,.28,.38],[164.81,146.83,.55,.8]],build:[[180,260,.1,0],[320,400,.12,.07]],bulldoze:[[110,45,.24,0]],error:[[130,100,.12,0],[100,80,.1,.15]],alert:[[440,660,.35,0],[660,440,.35,.38],[440,660,.35,.76]]};
export function createGameAudio(){
 const music=createGameMusic(),ambience=createCityAmbience();
 let settings={enabled:false,volume:40};try{const p=JSON.parse(localStorage.getItem(KEY));if(p&&typeof p.enabled==='boolean'&&Number.isFinite(p.volume))settings={enabled:p.enabled,volume:Math.min(100,Math.max(0,p.volume))};}catch{}
 let context,master,last=-Infinity,lastCity=null,incident=0;const active=new Set();
 const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(settings));}catch{}};
 const stop=()=>{for(const o of active)try{o.stop();}catch{}active.clear();};
 const gain=()=>{if(master)master.gain.setValueAtTime(settings.enabled&&!document.hidden?settings.volume/100*.22:0,context.currentTime);};
 async function unlock(){if(!settings.enabled)return;const Constructor=window.AudioContext||window.webkitAudioContext;if(!Constructor)throw Error('Audio is not available in this browser.');if(!context){context=new Constructor();master=context.createGain();master.connect(context.destination);gain();}if(context.state==='suspended')await context.resume();}
 function play(kind){if(!settings.enabled||!settings.volume||document.hidden||context?.state!=='running'||!AUDIO_CUES[kind])return;const now=context.currentTime;if(now-last<.05||active.size>12)return;last=now;for(const [from,to,duration,delay]of AUDIO_CUES[kind]){const o=context.createOscillator(),g=context.createGain(),start=now+delay;o.type=kind==='bulldoze'?'triangle':'sine';o.frequency.setValueAtTime(from,start);o.frequency.exponentialRampToValueAtTime(to,start+duration);g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(.65,start+.012);g.gain.exponentialRampToValueAtTime(.001,start+duration);o.connect(g);g.connect(master);active.add(o);o.onended=()=>{active.delete(o);o.disconnect();g.disconnect();};o.start(start);o.stop(start+duration+.02);}}
 document.addEventListener('pointerdown',()=>{unlock().catch(()=>{});},{capture:true});document.addEventListener('keydown',()=>{unlock().catch(()=>{});},{capture:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();gain();});
 return{music,ambience,get settings(){return{...settings};},play,async enable(value){settings.enabled=!!value;if(!value)stop();persist();gain();await unlock();},volume(value){settings.volume=Math.max(0,Math.min(100,Number(value)||0));persist();gain();},observe(c){if(c!==lastCity){lastCity=c;incident=c.emergency.started;return;}if(c.emergency.started!==incident){incident=c.emergency.started;if(c.emergency.active)play('alert');}}};
}
export function showAudioSettings(audio,dialog,notify){
 const s=audio.settings;dialog('Sound settings',`<p>Original synthesized sound effects for construction, clearing land, rejected construction, new emergencies, and authored scenario cues. Sound starts after a click or key press and stays quiet while this tab is hidden.</p><label><input id="audioEnabled" type="checkbox" ${s.enabled?'checked':''}> Enable sound effects</label><label>Sound effects volume <span id="audioLevel">${s.volume}%</span><input id="audioVolume" type="range" min="0" max="100" value="${s.volume}"></label><div class="actions"><button id="testBuildSound">Preview construction</button><button id="testAlertSound">Preview emergency alert</button><button id="testNoticeSound">Preview civic bell</button><button id="testAchievementSound">Preview celebration</button><button id="testTensionSound">Preview warning pulse</button></div><p class="fine">Sound is optional. Visual alerts and gameplay work with sound muted. These preferences stay in this browser.</p><section id="musicSettings"></section><section id="ambienceSettings"></section>`);
 showMusicSettings(audio.music,document.querySelector('#musicSettings'),notify);
 showAmbienceSettings(audio.ambience,document.querySelector('#ambienceSettings'),notify);
 document.querySelector('#audioEnabled').onchange=async e=>{try{await audio.enable(e.target.checked);if(e.target.checked)audio.play('build');}catch(error){notify(error.message);}};
 document.querySelector('#audioVolume').oninput=e=>{audio.volume(e.target.value);document.querySelector('#audioLevel').textContent=audio.settings.volume+'%';};
 for(const [id,cue] of [['testBuildSound','build'],['testAlertSound','alert'],['testNoticeSound','notice'],['testAchievementSound','achievement'],['testTensionSound','tension']])document.getElementById(id).onclick=async()=>{if(!audio.settings.enabled)return notify('Enable sound effects to hear a preview.');try{await audio.enable(true);audio.play(cue);}catch(error){notify(error.message);}};
}
